import{_ as t,o as a,c as r,ae as i}from"./chunks/framework.Dn6zxbF8.js";const l=JSON.parse('{"title":"Jiff","description":"","frontmatter":{"name":"Jiff","quadrant":"languages-and-frameworks","history":[{"edition":"2026.3","ring":"assess"}],"tags":["rust","datetime","time-zones"]},"headers":[],"relativePath":"radar/items/jiff.md","filePath":"radar/items/jiff.md"}'),s={name:"radar/items/jiff.md"};function n(o,e,d,f,h,m){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="jiff" tabindex="-1">Jiff <a class="header-anchor" href="#jiff" aria-label="Permalink to &quot;Jiff&quot;">​</a></h1><p>Jiff is the date and time library for <a href="./rust.html">Rust</a>. It models instants, civil dates and times, and zoned datetimes as distinct types, does time zone aware arithmetic and rounding, and reads the IANA time zone database from the system or embeds it when the target has none, so daylight saving transitions are handled by the library instead of by every caller.</p><p>It sits in Assess because it is the likely successor rather than a settled one. The maintainer of <a href="./chrono.html">Chrono</a> soft-deprecated it and chrono-tz in <a href="https://github.com/chronotope/chrono/issues/1768" target="_blank" rel="noreferrer">chronotope/chrono#1768</a> and named Jiff as the replacement they are comfortable recommending, which makes it the first library to prototype against when Chrono comes up.</p><p>What keeps it out of Trial is that Jiff is still on 0.x, so a minor version can carry breaking changes, and the RustSec unmaintained advisory for Chrono is deliberately waiting for Jiff 1.0. Learn the API, try it where a datetime dependency is new, and revisit the placement at 1.0.</p>',4)])])}const p=t(s,[["render",n]]);export{l as __pageData,p as default};
